  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * 2. Algorithm:
   *    1. If customer is null or customer.membershipPackage is null -> return price.
   *    2. If customer.membershipPackage.hasAward(DISCOUNTS) is false -> return price.
   *    3. Parse bookingTime and departureTime as datetime strings.
   *    4. If bookingTime is null, departureTime is null, or parsing fails -> return price.
   *    5. Calculate duration between bookingTime and departureTime.
   *    6. If duration >= 24 hours -> return price * 0.8 (rounded to one decimal place).
   *    7. Return price.
   * 3. Related Features: price, departureTime
   * 4. Related Classes: Customer, MembershipPackage, Award
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public double calculateDiscountedPrice(final Customer customer, final String bookingTime)
  {
    if (customer == null || customer.getMembershipPackage() == null) {
      return getPrice();
    }
    
    if (!customer.getMembershipPackage().hasAward(Award.DISCOUNTS)) {
      return getPrice();
    }
    
    if (bookingTime == null || getDepartureTime() == null) {
      return getPrice();
    }
    
    try {
      DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");
      LocalDateTime bookingDateTime = LocalDateTime.parse(bookingTime, formatter);
      LocalDateTime departureDateTime = LocalDateTime.parse(getDepartureTime(), formatter);
      
      long hoursBetween = ChronoUnit.HOURS.between(bookingDateTime, departureDateTime);
      
      if (hoursBetween >= 24) {
        double discountedPrice = getPrice() * 0.8;
        // Round to one decimal place
        return Math.round(discountedPrice * 10.0) / 10.0;
      }
      
      return getPrice();
    } catch (Exception e) {
      return getPrice();
    }
  }

  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * 2. Algorithm:
   *    1. If customer is null or customer.membershipPackage is null -> return 0.
   *    2. If customer.membershipPackage.hasAward(POINTS) is false -> return 0.
   *    3. Initialize totalPoints = 0.
   *    4. For each booking in bookings:
   *        a. If booking.customer == customer AND booking.isInMonth(currentMonth) is true:
   *           - totalPoints += booking.numberOfSeats * 5
   *    5. Return totalPoints.
   * 3. Related Features: bookings
   * 4. Related Classes: Customer, MembershipPackage, Award, Booking
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public int calculateMonthlyPoints(final Customer customer, final String currentMonth)
  {
    if (customer == null || customer.getMembershipPackage() == null) {
      return 0;
    }
    
    if (!customer.getMembershipPackage().hasAward(Award.POINTS)) {
      return 0;
    }
    
    int totalPoints = 0;
    
    for (Booking booking : getBookings()) {
      if (booking.getCustomer() == customer && booking.isInMonth(currentMonth)) {
        totalPoints += booking.getNumberOfSeats() * 5;
      }
    }
    
    return totalPoints;
  }

